import {
  BadRequestException,
  createParamDecorator,
  type ExecutionContext,
} from '@nestjs/common';
import type { Request } from 'express';
import { isUUID } from 'class-validator';

/**
 * Reads the mandatory `Idempotency-Key` header (a UUID generated by the
 * client once per checkout attempt). Missing or malformed → 400, as in the
 * IETF "Idempotency-Key HTTP Header Field" draft.
 */
export const IdempotencyKey = createParamDecorator(
  (_data: unknown, context: ExecutionContext): string => {
    const key = context
      .switchToHttp()
      .getRequest<Request>()
      .header('idempotency-key');
    if (!key || !isUUID(key))
      throw new BadRequestException(
        'The Idempotency-Key header is required and must be a UUID.',
      );
    return key.toLowerCase();
  },
);
